def write(name, fieldnames, rows):
    path = os.path.join(DATA, name)
    with open(path, "w", newline="", encoding="utf-8") as fh:
        w = csv.writer(fh, quoting=csv.QUOTE_MINIMAL)
        w.writerow(fieldnames)
        w.writerows(rows)
    print(f"  wrote {name}: {len(rows)} rows")


if __name__ == "__main__":
    os.makedirs(DATA, exist_ok=True)
    print("generating m5f19 data pack")
    write("m5f19_sources.csv",
          ["id", "publisher", "jurisdiction", "title", "url", "doc_type",
           "official", "fetched", "verbatim_notes"],
          SOURCES)
    write("m5f19_facts.csv",
          ["id", "topic", "verbatim_original", "english_gist", "instrument",
           "article", "source_id", "status"],
          FACTS)
    print("done")
